CREATE TABLE IF NOT EXISTS `#__intercom_connections` (`provider` varchar(64) NOT NULL, `envelope` mediumtext NOT NULL, PRIMARY KEY (`provider`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO `#__intercom_connections` (`provider`,`envelope`) VALUES ('cleverreach','');
CREATE TABLE IF NOT EXISTS `#__intercom_drafts` (`id` int unsigned NOT NULL AUTO_INCREMENT, `owner_id` int unsigned NOT NULL, `delivery_mode` varchar(8) NOT NULL DEFAULT 'live', `content` mediumtext NOT NULL, `revision` int unsigned NOT NULL DEFAULT 1, `tested_revision` int unsigned DEFAULT NULL, `tested_fingerprint` varchar(64) DEFAULT NULL, `state` varchar(24) NOT NULL DEFAULT 'draft', `filter_id` int unsigned DEFAULT NULL, `mailing_id` int unsigned NOT NULL DEFAULT 0, `send_at` bigint unsigned NOT NULL DEFAULT 0, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), KEY `owner` (`owner_id`), KEY `state_time` (`state`,`updated_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_filters` (`filter_id` int unsigned NOT NULL, `draft_id` int unsigned DEFAULT NULL, `group_id` int unsigned NOT NULL DEFAULT 0, `managed` tinyint unsigned NOT NULL DEFAULT 0, `reconciliation_status` varchar(32) NOT NULL DEFAULT '', `checked_at` datetime DEFAULT NULL, PRIMARY KEY (`filter_id`), UNIQUE KEY `draft` (`draft_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_revisions` (`id` int unsigned NOT NULL AUTO_INCREMENT, `draft_id` int unsigned NOT NULL, `revision` int unsigned NOT NULL, `content` mediumtext NOT NULL, `created_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `revision` (`draft_id`,`revision`), KEY `created` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_audit` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `actor_id` int unsigned NOT NULL, `event` varchar(80) NOT NULL, `draft_id` int unsigned NOT NULL DEFAULT 0, `context` mediumtext NOT NULL, `created_at` datetime NOT NULL, PRIMARY KEY (`id`), KEY `created` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_filter_creations` (`id` int unsigned NOT NULL AUTO_INCREMENT, `group_id` int unsigned NOT NULL, `remote_name` varchar(80) NOT NULL, `state` varchar(16) NOT NULL, `filter_id` int unsigned DEFAULT NULL, `created_at` datetime NOT NULL, `reconciliation_status` varchar(32) NOT NULL DEFAULT '', `checked_at` datetime DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `remote_name` (`remote_name`), KEY `group_state` (`group_id`,`state`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_types` (`id` int unsigned NOT NULL AUTO_INCREMENT, `asset_id` int unsigned NOT NULL DEFAULT 0, `type_key` varchar(64) NOT NULL, `suppression` varchar(128) NOT NULL, `category_id` int unsigned NOT NULL DEFAULT 0, `require_group` tinyint NOT NULL DEFAULT 0, `used` tinyint NOT NULL DEFAULT 0, `state` tinyint NOT NULL DEFAULT 1, `ordering` int NOT NULL DEFAULT 0, `revision` int unsigned NOT NULL DEFAULT 1, PRIMARY KEY (`id`), UNIQUE KEY `type_key` (`type_key`), UNIQUE KEY `suppression` (`suppression`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_type_translations` (`type_id` int unsigned NOT NULL, `language` varchar(12) NOT NULL, `name` varchar(255) NOT NULL, `description` text NOT NULL, `subject_prefix` varchar(80) NOT NULL DEFAULT '', `heading` varchar(255) NOT NULL DEFAULT '', PRIMARY KEY (`type_id`,`language`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_tags` (`list_id` int unsigned NOT NULL, `tag` varchar(200) NOT NULL, `labels` mediumtext NULL, `enabled` tinyint NOT NULL DEFAULT 0, `available` tinyint NOT NULL DEFAULT 1, `ordering` int NOT NULL DEFAULT 0, PRIMARY KEY (`list_id`,`tag`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_catalogues` (`list_id` int unsigned NOT NULL, `revision` int unsigned NOT NULL DEFAULT 1, `refreshed_at` datetime DEFAULT NULL, PRIMARY KEY (`list_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_archives` (`draft_id` int unsigned NOT NULL, `address` varchar(255) NOT NULL, `payload` mediumtext NOT NULL, `state` varchar(20) NOT NULL DEFAULT 'pending', `due_at` bigint unsigned NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`draft_id`), KEY `due` (`state`,`due_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_design` (`id` tinyint unsigned NOT NULL, `revision` int unsigned NOT NULL DEFAULT 1, `configuration` mediumtext NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO `#__intercom_design` (`id`,`configuration`) VALUES (1,'{}');
